# backend/thesis_bab1_bab2.py
"""Modul Pembangun BAB I dan BAB II Tesis Andre Juliansya"""

from docx.enum.text import WD_ALIGN_PARAGRAPH
from build_full_thesis_docx import p, h1, h2, h3, add_table_data, rapikan_tabel_dokumen

def build_bab_1(doc):
    h1(doc, "BAB I\nPENDAHULUAN")
    
    h2(doc, "1.1. Latar Belakang Masalah")
    p(doc, "Fenomena Aparatur Sipil Negara (ASN) di Indonesia secara umum masih sering dihadapkan pada tantangan rendahnya produktivitas, budaya kerja yang kaku, serta kualitas pelayanan publik yang dinilai lambat dan kurang responsif terhadap kebutuhan masyarakat (Juniarti, Setia, & Fahmi, 2022). Reformasi birokrasi saat ini menuntut ASN untuk bertransformasi dari sekadar pelaksana administratif menjadi pelayan publik yang lincah, inovatif, dan berorientasi hasil (Kurniawan & Kusumawardani, 2024). Namun, hambatan utama reformasi ini sering kali bukan disebabkan oleh faktor infrastruktur fisik, melainkan rendahnya komitmen dan keterikatan psikologis aparatur terhadap visi institusinya (Simatupang & Safitri, 2023).", indent=0.5, space_after=6)
    p(doc, "Sebagai garda terdepan fasilitasi investasi daerah, Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu (DPMPTSP) Provinsi Sumatera Selatan memegang peranan vital. Kinerja Pegawai (Z) di instansi ini sangat penting karena berdampak langsung terhadap kepuasan publik serta daya saing iklim investasi wilayah (Astuti et al., 2025). Sayangnya, kondisi empiris di lapangan menunjukkan adanya masalah serius pada kualitas kinerja pegawai, yang secara kuantitatif tecermin dari kegagalan instansi dalam memenuhi target ketepatan waktu penerbitan izin.", indent=0.5, space_after=6)

    # Tabel 1.1
    t1_headers = ["Tahun", "Target (%)", "Realisasi (%)", "Kesenjangan (%)", "Status"]
    t1_data = [
        ["2023", "90", "88,5", "-1,5", "Tidak Tercapai"],
        ["2024", "92", "85,2", "-6,8", "Tidak Tercapai"],
        ["2025", "95", "78,4", "-16,6", "Tidak Tercapai"]
    ]
    add_table_data(doc, "Tabel 1.1\nCapaian IKU Persentase Penerbitan Izin Tepat Waktu DPMPTSP Provinsi Sumatera Selatan", t1_headers, t1_data, "Sumber: LAKIP DPMPTSP Provinsi Sumatera Selatan, (2026)")

    p(doc, "Berdasarkan Tabel 1.1, kesenjangan (gap) antara target dan realisasi kinerja pelayanan terus melebar signifikan hingga mencapai -16,6% pada tahun 2025. Fenomena ini mengonfirmasi adanya masalah operasional yang krusial pada kuantitas dan ketepatan waktu penyelesaian tugas pegawai (LAKIP DPMPTSP, 2026).", indent=0.5, space_after=6)
    p(doc, "Penurunan capaian kinerja ini diindikasikan berakar pada krisis Employee Engagement (Y). Employee Engagement adalah kondisi psikologis di mana pegawai menyatukan aspek emosional, kognitif, dan fisiknya secara antusias ke dalam peran kerjanya (Rivai & Sagala, 2022). Variabel ini esensial karena mampu mengubah kepatuhan formal menjadi Discretionary Effort (upaya ekstra) yang melampaui standar pekerjaan (Kaswan, 2022). Secara teoretis, penelitian terdahulu membuktikan bahwa Employee Engagement yang tinggi memiliki pengaruh positif yang signifikan secara langsung terhadap peningkatan kinerja pegawai (Susanto & Wijaya, 2025). Namun, observasi di instansi ini justru menunjukkan gejala melemahnya keterikatan, terlihat dari fenomena Quiet Quitting, penurunan ketangguhan mental (Vigor), memudarnya kebanggaan (Dedication), serta pecahnya konsentrasi kerja (Absorption) saat jam sibuk operasional (Nurfitriani, 2022).", indent=0.5, space_after=6)
    p(doc, "Faktor krusial lain yang turut memengaruhi kinerja di lokasi penelitian adalah Motivasi Kerja (X1). Motivasi kerja merupakan daya dorong fundamental yang memicu semangat dan ketekunan pegawai untuk mengerahkan kemampuan terbaiknya demi tujuan organisasi (Kasmir, 2023). Pemenuhan motivasi sangat penting untuk menjaga konsistensi pelayanan di tengah tingginya rutinitas birokrasi (Afriliani et al., 2024). Fakta di lapangan menunjukkan iklim motivasi yang rendah akibat keluhan beban kerja yang tidak seimbang dan minimnya apresiasi (Adhelina et al., 2024). Namun demikian, telaah literatur menunjukkan masih terdapat celah penelitian (Research Gap) berupa inkonsistensi temuan terdahulu mengenai dampak langsung motivasi terhadap kinerja. Penelitian dari Noviantoro et al. (2022) dan Adhelina et al. (2024) secara konsisten membuktikan bahwa motivasi berpengaruh positif dan signifikan terhadap kinerja. Sebaliknya, temuan tersebut dibantah oleh penelitian Suwanto (2020) serta Hidayat dan Tjahjono (2022), yang secara mengejutkan membuktikan bahwa motivasi kerja tidak memiliki pengaruh yang signifikan terhadap peningkatan kinerja pegawai. Perdebatan hasil riset inilah yang menuntut dilakukannya pengujian kembali pada variabel motivasi.", indent=0.5, space_after=6)
    p(doc, "Selanjutnya, faktor pendukung kinerja yang juga bermasalah adalah Disiplin Kerja (X2). Disiplin kerja merepresentasikan bentuk kepatuhan dan kesadaran pegawai untuk menaati tata tertib serta prosedur operasional secara konsisten (Sutrisno, 2022). Penegakan disiplin sangat penting sebagai fondasi utama efisiensi birokrasi (Wijayanto et al., 2022). Secara teoretis, idealnya kedisiplinan berkorelasi positif dengan peningkatan kinerja. Namun, DPMPTSP Provinsi Sumatera Selatan justru menghadapi masalah pelanggaran kedisiplinan yang sangat kronis. Di sisi lain, dari tinjauan literatur empiris, masih ditemukan Research Gap yang memperdebatkan efektivitas disiplin terhadap kinerja. Penelitian dari Adhelina et al. (2024) dan Ridwan et al. (2025) secara kuat membuktikan bahwa kedisiplinan berdampak positif dan signifikan dalam meningkatkan kinerja. Akan tetapi, pandangan ini dibantah secara empiris oleh Simatupang dan Safitri (2023) serta Putra (2021), yang menemukan bahwa pendisiplinan tidak memiliki pengaruh yang signifikan terhadap capaian kinerja. Fenomena indisipliner di instansi dan adanya inkonsistensi temuan literatur inilah yang membuat pengujian atas disiplin kerja menjadi sangat relevan.", indent=0.5, space_after=6)

    # Tabel 1.2
    t2_headers = ["Bulan", "Hari Kerja Efektif", "Terlambat Datang", "Pulang Mendahului", "Tanpa Keterangan / Alpa (Hari)"]
    t2_data = [
        ["Januari", "22", "145", "82", "12"],
        ["Februari", "20", "160", "95", "18"],
        ["Maret", "21", "182", "110", "25"],
        ["April", "18", "210", "145", "32"],
        ["Mei", "21", "195", "120", "28"],
        ["Juni", "20", "188", "115", "20"],
        ["Juli", "22", "225", "150", "35"],
        ["Agustus", "21", "240", "165", "41"],
        ["September", "22", "215", "130", "29"],
        ["Oktober", "23", "255", "180", "45"],
        ["November", "21", "230", "155", "38"],
        ["Desember", "20", "275", "210", "52"],
        ["TOTAL", "251", "2.520", "1.657", "375"]
    ]
    add_table_data(doc, "Tabel 1.2\nRekapitulasi Absensi dan Pelanggaran Jam Kerja Pegawai DPMPTSP Provinsi Sumatera Selatan Tahun 2025", t2_headers, t2_data, "Sumber: DPMPTSP Prov. Sumsel, (2026)")

    p(doc, "Data Tabel 1.2 memperlihatkan tingginya angka pelanggaran fisik yang ekstrem (2.520 kasus keterlambatan, 1.657 kasus pulang awal, dan 375 hari alpa) sepanjang tahun 2025 (DPMPTSP Prov. Sumsel, 2026). Di sinilah letak Research Gap yang mendasar; Nuraini (2023) mengungkapkan bahwa pengawasan disiplin administratif yang terlalu kaku terkadang hanya melahirkan \"kepatuhan semu\" demi menghindari sanksi, tanpa benar-benar berkontribusi nyata pada peningkatan kinerja pelayanan publik itu sendiri.", indent=0.5, space_after=6)
    p(doc, "Menyikapi kebuntuan pendekatan administratif tersebut, Employee Engagement (Y) dihadirkan sebagai variabel mediasi. Keberadaan variabel ini sangat penting untuk membuktikan apakah keterikatan psikologis mampu menjembatani masalah motivasi dan kepatuhan semu menjadi kinerja yang optimal. Urgensi penggunaan variabel mediasi ini juga dilatarbelakangi oleh tingginya inkonsistensi (Research Gap) pada riset terdahulu. Pada jalur mediasi motivasi, Prabowo & Kui (2025) membuktikan bahwa Employee Engagement mampu memediasi motivasi terhadap kinerja, namun temuan ini secara kontras dibantah oleh Dewanata dan Fadila (2025) yang menyatakan engagement gagal memediasi hubungan tersebut. Pada jalur kedisiplinan, anomali senada ditemukan oleh Alamsyah et al. (2025) serta Ridwan et al. (2025) yang menemukan fakta bahwa Employee Engagement justru tidak mampu memediasi pengaruh disiplin kerja terhadap kinerja pegawai.", indent=0.5, space_after=6)
    p(doc, "Adanya penurunan target kinerja pelayanan secara empiris, krisis kedisiplinan operasional yang nyata, serta kuatnya kesenjangan hasil perdebatan riset terdahulu menjadikan penelitian konfirmatori ini memiliki urgensi yang sangat tinggi. Kebijakan manajerial birokrasi tidak lagi bisa bertumpu pada instruksi kaku semata, melainkan harus berbasis bukti (Evidence-Based Policy) (Afandi, 2023). Oleh karena itu, penulis mengangkat penelitian dengan judul, \"Peran Employee Engagement Dalam Memediasi Pengaruh Motivasi Kerja dan Disiplin Kerja Terhadap Kinerja Pegawai Pada Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan\".", indent=0.5, space_after=8)

    h2(doc, "1.2. Identifikasi Masalah")
    p(doc, "Berdasarkan uraian pada latar belakang masalah di atas, maka dapat diidentifikasi beberapa permasalahan yang terjadi pada Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan, antara lain:", space_after=4)
    id_points = [
        "1. Penurunan Kinerja Pelayanan: Kinerja pegawai dalam memproses administrasi perizinan belum optimal, yang dibuktikan dengan tidak tercapainya target Indikator Kinerja Utama (IKU) penerbitan izin tepat waktu, di mana gap penurunan mencapai 16,60% pada tahun 2025.",
        "2. Krisis Keterikatan Pegawai (Employee Engagement): Menggejalanya krisis Employee Engagement di kalangan aparatur, yang terindikasi dari menurunnya ketangguhan mental (Vigor), memudarnya rasa kebanggaan terhadap institusi (Dedication), serta mudah terpecahnya konsentrasi pegawai (Absorption) saat jam sibuk operasional.",
        "3. Iklim Motivasi Kerja yang Belum Memadai: Terdapat kesenjangan pemenuhan motivasi kerja, yang tecermin dari keluhan tingginya beban kerja loket perizinan yang tidak sebanding dengan proporsi waktu istirahat, minimnya apresiasi atas pencapaian, serta terbatasnya ruang aktualisasi diri pegawai.",
        "4. Pelemahan Kedisiplinan Kerja secara Masif: Tingkat kepatuhan dan disiplin pegawai sangat rendah, dibuktikan dengan tingginya rekam jejak pelanggaran jam kerja (lebih dari 2.500 kasus keterlambatan dan 375 hari alpa) serta kelalaian dalam mematuhi Standar Operasional Prosedur (SOP) baku.",
        "5. Terdapat Research Gap atau perdebatan akademis dari penelitian terdahulu mengenai apakah penerapan motivasi struktural dan penegakan disiplin administratif yang kaku di lingkungan birokrasi benar-benar efektif dalam menumbuhkan keterikatan emosional pegawai.",
        "6. Belum adanya kesepakatan empiris terkait keandalan Employee Engagement sebagai variabel mediasi, mengingat beberapa studi terbaru menunjukkan bahwa tingginya motivasi dan disiplin tidak selalu berhasil ditransformasikan menjadi kinerja yang unggul meskipun telah dimediasi oleh keterlibatan pegawai."
    ]
    for pt in id_points:
        p(doc, pt, indent=0.25, space_after=2)

    h2(doc, "1.3. Pembatasan Masalah")
    p(doc, "Dari uraian di latar belakang dan identifikasi masalah penulis membatasi permasalahan pada variabel Motivasi Kerja, Disiplin Kerja, Employee Engagement, dan Kinerja Pegawai.", indent=0.5, space_after=6)

    h2(doc, "1.4. Perumusan Masalah")
    p(doc, "Adapun masalah yang akan diselesaikan dalam penelitian ini adalah sebagai berikut :", space_after=4)
    rumusan = [
        "1. Apakah terdapat pengaruh Motivasi Kerja terhadap Employee Engagement Pegawai Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan?",
        "2. Apakah terdapat pengaruh Disiplin Kerja terhadap Employee Engagement Pegawai Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan?",
        "3. Apakah terdapat pengaruh Motivasi Kerja terhadap Kinerja Pegawai Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan?",
        "4. Apakah terdapat pengaruh Disiplin Kerja terhadap Kinerja Pegawai Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan?",
        "5. Apakah terdapat pengaruh Employee Engagement terhadap Kinerja Pegawai Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan?",
        "6. Apakah terdapat pengaruh Motivasi Kerja terhadap Kinerja Pegawai Melalui Employee Engagement Sebagai Variabel Mediasi Pada Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan?",
        "7. Apakah terdapat pengaruh Disiplin Kerja terhadap Kinerja Pegawai Melalui Employee Engagement Sebagai Variabel Mediasi Pada Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan?"
    ]
    for r in rumusan:
        p(doc, r, indent=0.25, space_after=2)

    h2(doc, "1.5. Tujuan Penelitian")
    p(doc, "Adapun tujuan penelitian yang sesuai dengan rumusan masalah diatas adalah untuk menganalisis, mengetahui dan membuktikan:", space_after=4)
    tujuan = [
        "1. Pengaruh Motivasi Kerja terhadap Employee Engagement Pegawai Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan.",
        "2. Pengaruh Disiplin Kerja terhadap Employee Engagement Pegawai Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan.",
        "3. Pengaruh Motivasi Kerja terhadap Kinerja Pegawai Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan.",
        "4. Pengaruh Disiplin Kerja terhadap Kinerja Pegawai Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan.",
        "5. Pengaruh Employee Engagement terhadap Kinerja Pegawai Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan.",
        "6. Pengaruh Motivasi Kerja terhadap Kinerja Pegawai Melalui Employee Engagement Sebagai Variabel Mediasi Pada Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan.",
        "7. Pengaruh Disiplin Kerja terhadap Kinerja Pegawai Melalui Employee Engagement Sebagai Variabel Mediasi Pada Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Provinsi Sumatera Selatan."
    ]
    for t in tujuan:
        p(doc, t, indent=0.25, space_after=2)

    h2(doc, "1.6. Kegunaan Penelitian")
    p(doc, "Penelitian ini diharapkan dapat memberikan kegunaan atau manfaat yang berarti, baik dari tinjauan teoritis maupun praktis. Adapun rincian kegunaan dari penelitian ini adalah sebagai berikut:", space_after=4)
    p(doc, "1. Secara Teoritis :", bold=True, space_after=2)
    p(doc, "Secara teoritis, hasil penelitian ini diharapkan dapat memberikan sumbangsih pemikiran dan memperluas wawasan keilmuan, antara lain:", indent=0.25, space_after=2)
    p(doc, "a) Memberikan kontribusi nyata terhadap pengembangan keilmuan di bidang Manajemen Sumber Daya Manusia (MSDM), khususnya dalam memperkaya literatur mengenai peran Employee Engagement sebagai variabel mediasi antara Motivasi Kerja dan Disiplin Kerja terhadap Kinerja Pegawai.", indent=0.5, space_after=2)
    p(doc, "b) Memberikan jawaban dan pembuktian empiris atas perdebatan akademis dari studi-studi terdahulu terkait efektivitas dorongan motivasi struktural dan penegakan disiplin administratif dalam menumbuhkan keterikatan emosional pegawai di lingkungan birokrasi pemerintahan.", indent=0.5, space_after=2)
    p(doc, "c) Dapat dijadikan sebagai bahan rujukan, referensi, atau acuan dasar bagi akademisi maupun peneliti selanjutnya yang berminat melakukan kajian lanjutan dengan variabel, model struktural, atau objek penelitian yang sejenis.", indent=0.5, space_after=4)
    
    p(doc, "2. Secara Praktis :", bold=True, space_after=2)
    p(doc, "Secara praktis, hasil penelitian ini diharapkan dapat memberikan manfaat langsung bagi pihak-pihak yang berkepentingan, antara lain:", indent=0.25, space_after=2)
    p(doc, "a) Bagi Instansi (DPMPTSP Provinsi Sumatera Selatan): Hasil penelitian ini dapat menjadi landasan evaluasi dan masukan berbasis bukti (Evidence-Based Policy) bagi organisasi dalam menyusun strategi pemecahan masalah guna meningkatkan capaian target Indikator Kinerja Utama (IKU), khususnya terkait ketepatan waktu penerbitan izin.", indent=0.5, space_after=2)
    p(doc, "b) Bagi Pimpinan dan Pengambil Kebijakan: Memberikan gambaran objektif mengenai kondisi riil motivasi, tingkat kedisiplinan, dan keterikatan aparatur di lapangan. Hal ini sangat berguna sebagai bahan pertimbangan manajerial dalam memformulasikan kebijakan insentif, penataan ulang beban kerja, serta pendekatan penegakan disiplin yang lebih efektif untuk menekan angka pelanggaran jam kerja.", indent=0.5, space_after=2)
    p(doc, "c) Bagi Pegawai (ASN dan PPPK): Diharapkan dapat menumbuhkan kesadaran diri aparatur mengenai pentingnya memiliki keterikatan psikologis dan emosional (Employee Engagement) terhadap instansi, sehingga mampu bertransformasi dari sekadar pelaksana administratif yang menggugurkan kewajiban menjadi pelayan publik yang berdedikasi tinggi dan berkinerja prima.", indent=0.5, space_after=8)
    rapikan_tabel_dokumen(doc)
    doc.add_page_break()

def build_bab_2(doc):
    h1(doc, "BAB II\nKAJIAN TEORITIS DAN HIPOTESIS PENELITIAN")
    
    h2(doc, "2.1. Kajian Teoritis")
    
    # 2.1.1 Kinerja
    h3(doc, "2.1.1. Kinerja")
    p(doc, "a) Pengertian Kinerja", bold=True, space_after=2)
    p(doc, "Kinerja merupakan salah satu aspek penting dalam organisasi karena mencerminkan tingkat keberhasilan pegawai dalam melaksanakan tugas dan tanggung jawab yang diberikan. Kinerja menjadi indikator untuk menilai efektivitas, produktivitas, serta kontribusi pegawai dalam mendukung pencapaian tujuan organisasi. Oleh karena itu, peningkatan kinerja pegawai menjadi perhatian utama setiap organisasi agar mampu mencapai target yang telah ditetapkan.", indent=0.5, space_after=4)
    p(doc, "Mangkunegara (2022) menjelaskan bahwa kinerja pegawai adalah hasil kerja yang dicapai baik secara kualitas maupun kuantitas dalam melaksanakan tugas sesuai dengan tanggung jawab yang diberikan. Definisi ini menunjukkan bahwa kinerja tidak hanya berfokus pada jumlah hasil kerja, tetapi juga pada kualitas pekerjaan yang dihasilkan oleh pegawai.", indent=0.5, space_after=4)
    p(doc, "Kasmir (2023) mendefinisikan kinerja sebagai hasil kerja dan perilaku kerja seseorang dalam suatu periode tertentu yang disesuaikan dengan standar serta tujuan yang telah ditetapkan organisasi. Dengan demikian, penilaian kinerja tidak hanya didasarkan pada hasil akhir, tetapi juga mencakup proses dan perilaku yang ditunjukkan selama pelaksanaan pekerjaan.", indent=0.5, space_after=4)
    p(doc, "Afandi (2023) menyatakan bahwa kinerja merupakan hasil kerja seseorang atau kelompok yang dilaksanakan sesuai dengan wewenang dan tanggung jawab masing-masing, serta tetap memperhatikan aspek hukum, moral, dan etika. Konsep ini menegaskan bahwa pencapaian kinerja tidak hanya diukur dari hasil, tetapi juga dari cara memperoleh hasil tersebut.", indent=0.5, space_after=4)
    p(doc, "Berdasarkan berbagai pendapat tersebut, dapat disimpulkan bahwa kinerja adalah hasil kerja dan perilaku kerja yang ditunjukkan oleh individu maupun kelompok dalam melaksanakan tugas dan tanggung jawabnya, baik secara kualitas maupun kuantitas, untuk mencapai tujuan organisasi sesuai dengan standar yang telah ditetapkan, dengan tetap memperhatikan aspek kemampuan, ketepatan waktu, etika, serta peraturan yang berlaku.", indent=0.5, space_after=6)

    p(doc, "b) Faktor – faktor yang mempengaruhi Kinerja", bold=True, space_after=2)
    p(doc, "Juniarti, Setia, & Fahmi (2022) menyatakan bahwa faktor yang mempengaruhi kinerja antara lain :\n1. Faktor Kemampuan: Secara psikologis, kemampuan (ability) pegawai terdiri dari kemampuan potensi dengan pendidikan yang memadai untuk jabatannya dan terampil dalam mengerjakan pekerjaan sehari-hari, maka ia akan lebih mudah mencapai kinerja yang diharapkan (the right man in place, the man on the right job).\n2. Faktor Motivasi: Motivasi terbentuk dari sikap pegawai dalam menghadapi situasi, yang menggerakkan pegawai secara terarah untuk mencapai tujuan organisasi.", indent=0.5, space_after=4)
    p(doc, "Rakhmalina (2021) menjelaskan bahwa kinerja dipengaruhi oleh beberapa faktor yang berkaitan dengan hasil maupun perilaku kerja individu, antara lain: 1) Kemampuan dan Keahlian, 2) Pengetahuan, 3) Rancangan Kerja, 4) Kepribadian, 5) Employee Engagement, 6) Kepemimpinan, 7) Budaya Organisasi, 8) Kepuasan Kerja, 9) Loyalitas, dan 10) Disiplin Kerja.", indent=0.5, space_after=6)

    p(doc, "c) Dimensi dan Indikator Kinerja", bold=True, space_after=2)
    p(doc, "Ulya & Rahmah (2025) menjelaskan, dimensi dan indikator kinerja pegawai dapat diukur sebagai berikut:\n1. Jumlah Pekerjaan (Kuantitas): Pencapaian volume pekerjaan, Pencapaian target tugas rutin, Penyelesaian tugas tambahan.\n2. Kualitas Pekerjaan: Kesesuaian kerja dengan SOP, Tingkat ketelitian kerja, Kelengkapan hasil pekerjaan.\n3. Ketepatan Waktu: Penyelesaian tugas sesuai jadwal, Kecepatan merespons tugas, Prioritas waktu pengerjaan.\n4. Kehadiran (Absensi): Kepatuhan jam masuk dan pulang, Kehadiran efektif di kantor, Kepatuhan prosedur izin/cuti.\n5. Kemampuan Kerja Sama: Keterlibatan aktif dalam tim, Kelancaran koordinasi antarpegawai, Inisiatif membantu rekan kerja.", indent=0.5, space_after=4)
    p(doc, "Berdasarkan berbagai penjelasan di atas, dapat disimpulkan bahwa kinerja adalah pencapaian prestasi kerja dalam periode tertentu (Khaeruman, 2022). Secara operasional, berdasarkan pendapat Ulya & Rahmah (2025), kinerja dalam penelitian ini diukur melalui dimensi Jumlah Pekerjaan (Kuantitas), Kualitas Pekerjaan, Ketepatan Waktu, Kehadiran (Absensi) dan Kemampuan Kerja Sama.", indent=0.5, space_after=8)

    # 2.1.2 Employee Engagement
    h3(doc, "2.1.2. Employee Engagement")
    p(doc, "a) Pengertian Employee Engagement", bold=True, space_after=2)
    p(doc, "Employee Engagement merupakan salah satu konsep penting dalam manajemen sumber daya manusia yang menggambarkan tingkat keterikatan, komitmen, dan keterlibatan pegawai terhadap pekerjaan maupun organisasinya. Tingginya Employee Engagement mendorong pegawai untuk bekerja tidak hanya demi memenuhi kewajiban formal, tetapi juga untuk memberikan kontribusi terbaik bagi keberhasilan organisasi. Oleh karena itu, Employee Engagement sering dikaitkan dengan peningkatan produktivitas, loyalitas, serta pencapaian tujuan organisasi secara berkelanjutan.", indent=0.5, space_after=4)
    p(doc, "Kaswan (2022) menjelaskan bahwa Employee Engagement merupakan komitmen emosional dan intelektual yang dimiliki karyawan terhadap organisasi dan keberhasilannya, sehingga mendorong mereka untuk memberikan upaya tambahan (Discretionary Effort) yang melampaui tuntutan pekerjaan formal. Keterikatan tersebut menunjukkan adanya hubungan yang kuat antara pegawai dengan organisasi tempatnya bekerja.", indent=0.5, space_after=4)
    p(doc, "Rivai & Sagala (2022) menjelaskan bahwa keterlibatan pegawai merupakan keadaan ketika individu menyatukan aspek emosional, kognitif, dan fisiknya ke dalam peran kerja yang dijalankan. Keterlibatan tersebut tercermin melalui antusiasme, kebanggaan, dan dedikasi yang tinggi dalam melaksanakan pekerjaan.", indent=0.5, space_after=4)
    p(doc, "Sutrisno (2022) menyatakan bahwa keterlibatan karyawan merupakan bentuk partisipasi aktif dan menyeluruh dalam pekerjaan, di mana individu mencurahkan perhatian, pikiran, serta tenaganya secara optimal untuk mendukung kemajuan organisasi.", indent=0.5, space_after=4)
    p(doc, "Kasmir (2023) menambahkan bahwa keterikatan karyawan merupakan bentuk kepuasan dan komitmen yang mendalam terhadap organisasi. Pegawai yang engaged tidak hanya bekerja untuk memenuhi kewajiban, tetapi juga memiliki dorongan yang kuat untuk melihat organisasi berkembang dan mencapai kesuksesan.", indent=0.5, space_after=4)
    p(doc, "Berdasarkan berbagai pendapat tersebut, dapat disimpulkan bahwa Employee Engagement adalah kondisi psikologis positif yang mencerminkan keterikatan emosional, kognitif, dan perilaku pegawai terhadap pekerjaan serta organisasi, yang ditunjukkan melalui semangat, dedikasi, partisipasi aktif, loyalitas, dan kesediaan untuk memberikan kontribusi terbaik guna mendukung pencapaian tujuan organisasi.", indent=0.5, space_after=6)

    p(doc, "b) Dimensi dan Indikator Employee Engagement", bold=True, space_after=2)
    p(doc, "Harefa, Halawa, & Waruwu (2025) menjelaskan bahwa, dimensi dan indikator Employee Engagement dapat diukur yaitu sebagai berikut:\n1. Vigor: Energi kerja, Ketangguhan, Daya tahan.\n2. Dedication: Antusiasme, Kebanggaan, Inspirasi.\n3. Absorption: Fokus kerja, Tenggelam dalam pekerjaan, Konsentrasi.", indent=0.5, space_after=4)
    p(doc, "Berdasarkan beberapa penjelasan di atas, dapat disimpulkan bahwa Employee Engagement merupakan keadaan ketika individu menyatukan aspek emosional, kognitif, dan fisiknya ke dalam peran kerja yang dijalankan (Rivai & Sagala, 2022). Adapun secara operasional, pengukuran Employee Engagement dalam penelitian ini merujuk pada konsep Harefa, Halawa, dan Waruwu (2025) yang mencakup dimensi Vigor, dimensi Dedication, dan dimensi Absorption.", indent=0.5, space_after=8)

    # 2.1.3 Motivasi Kerja
    h3(doc, "2.1.3. Motivasi Kerja")
    p(doc, "a) Pengertian Motivasi Kerja", bold=True, space_after=2)
    p(doc, "Motivasi kerja merupakan salah satu faktor penting yang memengaruhi perilaku dan kinerja pegawai dalam organisasi. Melalui motivasi, pegawai terdorong untuk bekerja dengan sungguh-sungguh, mengerahkan kemampuan terbaiknya, serta mempertahankan semangat kerja dalam mencapai tujuan yang telah ditetapkan. Oleh karena itu, motivasi kerja sering dipandang sebagai kekuatan yang mengarahkan, menggerakkan, dan mempertahankan perilaku individu dalam lingkungan kerja.", indent=0.5, space_after=4)
    p(doc, "Sutrisno (2022) menjelaskan bahwa motivasi kerja merupakan dorongan yang berasal dari dalam maupun luar diri seseorang untuk melakukan suatu aktivitas atau pekerjaan tertentu. Dorongan tersebut berfungsi sebagai motor penggerak yang memengaruhi perilaku individu dalam mencapai tujuan yang diinginkan.", indent=0.5, space_after=4)
    p(doc, "Kasmir (2023) mengemukakan bahwa motivasi kerja merupakan daya dorong atau kemauan yang timbul dalam diri seseorang sehingga individu bersedia mengerahkan seluruh kemampuan, tenaga, dan keahliannya untuk mencapai tujuan organisasi secara maksimal. Hal ini menunjukkan bahwa motivasi berperan sebagai energi yang mendorong seseorang untuk memberikan kontribusi terbaik bagi organisasi.", indent=0.5, space_after=4)
    p(doc, "Afandi (2023) menjelaskan bahwa motivasi kerja merupakan dorongan positif yang diberikan kepada pegawai agar mereka bersedia bekerja sama dan bekerja secara efektif dalam mencapai target maupun tujuan organisasi. Motivasi dalam konteks ini menjadi alat yang mampu meningkatkan semangat dan produktivitas kerja pegawai.", indent=0.5, space_after=4)
    p(doc, "Berdasarkan berbagai pendapat tersebut, dapat disimpulkan bahwa motivasi kerja adalah dorongan yang berasal dari faktor internal maupun eksternal yang mampu membangkitkan, mengarahkan, dan mempertahankan perilaku individu dalam bekerja. Motivasi mendorong pegawai untuk mengerahkan kemampuan, energi, dan ketekunannya secara optimal guna mencapai tujuan pribadi maupun tujuan organisasi secara efektif dan berkelanjutan.", indent=0.5, space_after=6)

    p(doc, "b) Dimensi dan Indikator Motivasi Kerja", bold=True, space_after=2)
    p(doc, "Farhan & Indriyaningrum (2025) mengemukakan bahwa, dimensi dan indikator motivasi kerja dapat diukur sebagai berikut:\n1. Kebutuhan Fisiologi: Kesesuaian gaji/tunjangan, Kecukupan waktu istirahat, Kenyamanan fasilitas kerja.\n2. Kebutuhan Rasa Aman: Keamanan lingkungan kerja, Jaminan kesehatan pegawai, Jaminan keselamatan kerja.\n3. Kebutuhan Merasa Memiliki (Sosial): Hubungan baik dengan atasan, Hubungan harmonis antarpegawai, Kekompakan rekan kerja.\n4. Kebutuhan untuk Dihargai: Apresiasi dari pimpinan, Penghargaan atas prestasi, Pengakuan atas keahlian.\n5. Kebutuhan Mengaktualisasi Diri: Kesempatan menyampaikan ide, Pelatihan pengembangan diri, Kesempatan pengembangan karier.", indent=0.5, space_after=4)
    p(doc, "Berdasarkan beberapa penjelasan di atas, dapat disimpulkan bahwa motivasi kerja merupakan dorongan yang berasal dari dalam maupun luar diri seseorang untuk melakukan suatu aktivitas atau pekerjaan tertentu (Sutrisno, 2022). Adapun pengukuran motivasi kerja secara operasional merujuk pada indikator dari Farhan dan Indriyaningrum (2025) yang meliputi kebutuhan fisiologi, kebutuhan rasa aman, kebutuhan merasa memiliki (sosial), kebutuhan untuk dihargai, dan kebutuhan mengaktualisasi diri.", indent=0.5, space_after=8)

    # 2.1.4 Disiplin Kerja
    h3(doc, "2.1.4. Disiplin Kerja")
    p(doc, "a) Pengertian Disiplin Kerja", bold=True, space_after=2)
    p(doc, "Disiplin kerja merupakan salah satu aspek penting dalam pengelolaan sumber daya manusia karena berkaitan dengan tingkat kepatuhan pegawai terhadap berbagai aturan, prosedur, dan norma yang berlaku dalam organisasi. Tingkat disiplin yang baik akan membantu organisasi menciptakan lingkungan kerja yang tertib, efektif, dan produktif. Oleh sebab itu, disiplin kerja sering dipandang sebagai fondasi utama dalam mendukung pencapaian tujuan organisasi.", indent=0.5, space_after=4)
    p(doc, "Ridwan et al. (2025) menjelaskan bahwa disiplin kerja merupakan sikap atau perilaku yang menunjukkan kesetiaan dan ketaatan individu maupun kelompok terhadap peraturan organisasi, baik yang tertulis maupun tidak tertulis. Dalam kajian yang lebih sederhana, Oktarisa et al. (2026) mendefinisikan disiplin kerja sebagai tingkat kepatuhan karyawan terhadap berbagai peraturan dan prosedur yang telah ditetapkan oleh organisasi.", indent=0.5, space_after=4)
    p(doc, "Kasmir (2023) mendefinisikan disiplin kerja sebagai sikap, tingkah laku, dan perbuatan yang mencerminkan kesadaran serta kesediaan pegawai dalam mematuhi seluruh aturan, tata tertib, dan prosedur yang telah ditetapkan organisasi. Kepatuhan tersebut menjadi indikator penting dalam menilai kualitas perilaku kerja pegawai.", indent=0.5, space_after=4)
    p(doc, "Afandi (2023) mengemukakan bahwa disiplin kerja adalah tata tertib atau peraturan yang dibuat oleh manajemen untuk ditaati oleh seluruh pegawai. Kepatuhan terhadap aturan tersebut mencerminkan besarnya rasa tanggung jawab pegawai terhadap tugas dan kewajiban yang diberikan kepadanya.", indent=0.5, space_after=4)
    p(doc, "Wibowo (2023) menyatakan bahwa disiplin kerja merupakan kondisi yang terbentuk melalui serangkaian perilaku yang menunjukkan nilai-nilai ketaatan, kepatuhan, keteraturan, dan ketertiban dalam organisasi. Oleh karena itu, disiplin dapat dilihat sebagai budaya perilaku yang berkembang secara berkelanjutan dalam lingkungan kerja.", indent=0.5, space_after=4)
    p(doc, "Berdasarkan berbagai pendapat tersebut, dapat disimpulkan bahwa disiplin kerja adalah sikap, perilaku, dan kesediaan pegawai untuk mematuhi serta melaksanakan seluruh peraturan, prosedur, norma, dan ketentuan organisasi secara sadar dan bertanggung jawab. Disiplin kerja tercermin melalui ketaatan, keteraturan, konsistensi, serta kesediaan menerima konsekuensi atas pelanggaran yang dilakukan, sehingga dapat mendukung efektivitas, efisiensi, dan pencapaian tujuan organisasi.", indent=0.5, space_after=6)

    p(doc, "b) Dimensi dan Indikator Disiplin Kerja", bold=True, space_after=2)
    p(doc, "Prasetio, Ruminta, & Akbar (2025), dimensi dan indikator disiplin kerja dapat diukur yaitu sebagai berikut:\n1. Ketepatan Waktu: Penyelesaian tugas tepat waktu, Pemanfaatan jam kerja efektif (efisiensi waktu), Ketepatan waktu pelaporan hasil.\n2. Tanggung Jawab Kerja: Pencapaian target pekerjaan, Kesiapan menerima evaluasi kerja, Keberanian menanggung risiko tugas.\n3. Ketaatan: Kepatuhan pada aturan jam kerja, Kepatuhan terhadap instruksi pimpinan, Kepatuhan pada Standar Operasional Prosedur (SOP).", indent=0.5, space_after=4)
    p(doc, "Berdasarkan beberapa penjelasan di atas, dapat disimpulkan bahwa disiplin kerja merupakan kondisi yang terbentuk melalui serangkaian perilaku yang menunjukkan nilai-nilai ketaatan, kepatuhan, keteraturan, dan ketertiban dalam organisasi (Wibowo, 2023). Secara operasional, Prasetio, Ruminta, dan Akbar (2025) mengukur disiplin kerja melalui tiga dimensi utama, yaitu ketepatan waktu, tanggung jawab kerja, dan ketaatan.", indent=0.5, space_after=8)

