    # 2.3 Kerangka Berpikir
    h2(doc, "2.3. Kerangka Berpikir")
    p(doc, "Berdasarkan kajian pustaka baik teoritis maupun empiris, maka kerangka pemikiran dalam penelitian ini terdiri dari:", space_after=4)
    kb_points = [
        ("1) Pengaruh Motivasi Kerja terhadap Employee Engagement", "Sutrisno (2022) mendefinisikan, motivasi kerja merupakan dorongan internal dan eksternal yang membangkitkan semangat serta mengarahkan perilaku pegawai untuk bekerja secara sungguh-sungguh demi mencapai tujuan organisasi. Karyawan yang termotivasi dengan baik akan merasa lebih dihargai dan memiliki antusiasme yang tinggi dalam menjalankan perannya, yang pada gilirannya menciptakan ikatan psikologis yang kuat antara individu dengan pekerjaannya. Dengan demikian, pemberian motivasi yang tepat menjadi katalisator bagi terciptanya Employee Engagement yang mendalam di lingkungan organisasi. Dukungan empiris ditunjukkan oleh penelitian Junengsih et al. (2022) dalam Firmansyah & Rochdianingrum (2025) yang membuktikan bahwa motivasi kerja memiliki pengaruh positif dan signifikan terhadap Employee Engagement."),
        ("2) Pengaruh Disiplin Kerja terhadap Employee Engagement", "Mangkunegara (2022) mengemukakan bahwa disiplin kerja adalah kesadaran dan kesediaan seseorang untuk menaati semua peraturan perusahaan serta norma-norma sosial yang berlaku di lingkungan kerjanya. Disiplin yang diterapkan dengan baik menciptakan tatanan perilaku yang tertib, sehingga karyawan memiliki acuan yang jelas dalam bekerja. Ketaatan terhadap jam kerja, prosedur, dan aturan organisasi ini membangun rasa percaya dan stabilitas psikologis, yang pada gilirannya mendorong keterikatan emosional dan dedikasi karyawan terhadap organisasi atau Employee Engagement. Dukungan empiris ditemukan dalam penelitian Irmawati & Rudini (2024) serta Alamsyah et al. (2025)."),
        ("3) Pengaruh Motivasi Kerja terhadap Kinerja", "Sutrisno (2022) mendefinisikan motivasi kerja sebagai faktor pendorong seseorang untuk melakukan suatu aktivitas guna mencapai tujuan yang diinginkan. Motivasi kerja berfungsi sebagai penggerak energi fisik dan mental yang membuat seseorang antusias dalam menyelesaikan tugas-tugasnya dengan efisien. Pegawai yang termotivasi dengan baik akan memiliki orientasi pencapaian yang tinggi, sehingga tingkat kuantitas maupun kualitas pekerjaannya cenderung memenuhi atau melampaui standar yang ditetapkan oleh organisasi. Temuan penelitian oleh Wulandari et al. (2024) dan Alamsyah et al. (2025) mengonfirmasi hubungan positif dan signifikan ini."),
        ("4) Pengaruh Disiplin Kerja terhadap Kinerja", "Rivai & Sagala (2022) menegaskan bahwa disiplin kerja merupakan alat manajemen untuk meningkatkan kesadaran dan kesediaan pegawai dalam mematuhi peraturan perusahaan. Disiplin yang tinggi mencerminkan integritas dan tanggung jawab pegawai dalam menjaga efektivitas proses operasional kantor. Ketika pegawai disiplin dalam hal waktu, prosedur, dan penggunaan fasilitas kantor, maka produktivitas kerja akan meningkat, yang secara langsung berpengaruh pada pencapaian target kinerja pegawai tersebut. Penelitian Noviantoro et al. (2022) serta Oktarisa et al. (2026) membuktikan bahwa kedisiplinan berbanding lurus dengan hasil kerja yang dicapai."),
        ("5) Pengaruh Employee Engagement terhadap Kinerja", "Afandi (2023) berpandangan bahwa Employee Engagement adalah kondisi psikologis positif yang ditandai dengan semangat (Vigor), dedikasi, dan keterlibatan penuh (Absorption) dalam pekerjaan. Karyawan yang terlibat aktif secara psikologis akan mencurahkan pikiran dan energinya untuk menyelesaikan tantangan kerja dengan solusi terbaik. Keterikatan ini menumbuhkan loyalitas dan rasa memiliki yang tinggi, yang membuat karyawan bekerja secara proaktif untuk mencapai sasaran organisasi, sehingga kinerja individu meningkat pesat. Dukungan empiris ditemukan dalam penelitian Pratama et al. (2025) dan Tarisa Azahra & Rohimat Nurhasan (2025)."),
        ("6) Pengaruh Motivasi Kerja terhadap Kinerja melalui Employee Engagement Sebagai Variabel Mediasi", "Kaswan (2022) menjelaskan bahwa keterikatan psikologis atau Employee Engagement bertindak sebagai motor penggerak sejati yang mampu mengubah sekadar dorongan dasar menjadi upaya ekstra (Discretionary Effort) yang melampaui tuntutan pekerjaan formal. Pegawai yang telah mendapatkan dorongan motivasi kerja yang baik akan merasa lebih dihargai, sehingga menumbuhkan antusiasme dan keterikatan emosional (engagement) yang mendalam terhadap organisasinya. Keterikatan psikologis inilah yang pada akhirnya ditransformasikan menjadi kinerja pegawai yang unggul. Hubungan mediasi ini didukung oleh temuan empiris dari Prabowo & Kui (2025)."),
        ("7) Pengaruh Disiplin Kerja terhadap Kinerja melalui Employee Engagement Sebagai Variabel Mediasi", "Mangkunegara (2022) menyatakan bahwa penegakan tata tertib dan disiplin kerja dirancang untuk menciptakan keteraturan dan stabilitas operasional dalam suatu organisasi. Habituasi kepatuhan yang terus-menerus ini secara logika akan memperkuat fokus, dedikasi, serta kesadaran pegawai (Rivai & Sagala, 2022), sehingga mampu menumbuhkan keterlibatan kerja (Employee Engagement). Ketika pegawai sudah terbentuk kedisiplinannya dan terikat secara emosional dengan perannya, maka target kinerja institusi akan jauh lebih mudah direalisasikan secara berkualitas dan tepat waktu.")
    ]
    for sub, desc in kb_points:
        p(doc, sub, bold=True, space_before=4, space_after=2)
        p(doc, desc, indent=0.5, space_after=4)

