    p(doc, "Gambar 2.1\nKerangka Berpikir\n(Motivasi Kerja [X1] & Disiplin Kerja [X2] --> Employee Engagement [Y] --> Kinerja Pegawai [Z])", bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, space_before=6, space_after=2)
